from pathlib import Path
import json,gzip,collections,statistics
p=Path('docs/qa/progression-nature-three-2026-11-09');files=sorted(p.glob('*.json'));data=[json.load(open(f))for f in files]if files else json.loads(gzip.decompress((p/'results.json.gz').read_bytes()))['runs'];assert len(data)==18
old=json.loads(gzip.decompress(Path('docs/qa/progression-2026-11-09/results.json.gz').read_bytes()))['runs'];names={'druida_sombrio':'Druida Sombrio','avatar_da_natureza':'Avatar da Natureza','protetor_da_floresta':'Protetor da Floresta'}
lines=['# Ajustes e análise — três rotas da Natureza — 09/11/2026','','Meta: chegar ao Paradoxo; vencer o Soberano não é requisito.','','## Alterações aplicadas','','- Druida Sombrio: Podridão passa de +30% para +45% nos DOTs naturais; devolução do Ciclo Natural passa de 10% para 15%. O Druida base e o Avatar mantêm a devolução anterior.','- Avatar da Natureza: Forma Verdadeira custa piso(95% da mana máxima) e concede +40% de ataque. Duração e fórmula do ataque básico preservadas: 1,7A + r durante a forma, com A sendo o ataque ativo.','- Protetor da Floresta: Casulo de Vinhas passa de piso(1,4A + 1,4P) para piso(1,7A + 1,7P).','- A esquiva de 25% do Deus da Ruína, solicitada antes, foi mantida nesta rodada.','','## Método','','18 campanhas novas: três rotas × três sementes (101, 202, 303) × equipamento de referência ou conjuntos por rota. Motor, política e preparação acelerada da análise anterior: pontos equilibrados, recuperação entre lutas, nível e equipamento concedidos após falhas; desistência apenas após 11 mortes no nível 100 com seis lendários. Sem poções, arena ou dungeon. O histórico pode continuar no Paradoxo, mas o sucesso desta análise considera somente alcançá-lo. Não mede custo ou duração real de farm, nem usa uma política ótima de habilidades.','','A comparação anterior é descritiva: a rodada atual também usa a esquiva de 25% do Deus da Ruína; não isola causalmente cada ajuste.','','| Rota | Equipamentos | Antes: chegaram ao Paradoxo | Agora: chegaram ao Paradoxo | Parada atual | Mortes medianas totais |','| --- | --- | ---: | ---: | --- | ---: |']
for route,label in names.items():
 for scenario in ['reference','sets']:
  a=[r for r in data if r['route']==route and r['scenario']==scenario];b=[r for r in old if r['route']==route and r['scenario']==scenario];stops=collections.Counter(r['region']for r in a)
  lines.append(f"| {label} | {'Referência'if scenario=='reference'else'Conjuntos'} | {sum(r['region']=='Paradoxo'for r in b)}/3 | {sum(r['region']=='Paradoxo'for r in a)}/3 | {'; '.join(f'{k} ({v}/3)'for k,v in stops.items())} | {statistics.median(r['deaths']for r in a)} |")
lines+=['','## Gargalos por rota','','| Rota | Inimigos com mais derrotas |','| --- | --- |']
for route,label in names.items():
 counter=collections.Counter(e['foe']['name']for r in data if r['route']==route for e in r['encounters']if e['outcome']=='death')
 lines.append(f"| {label} | {'; '.join(f'{k}: {v}'for k,v in counter.most_common(3))} |")
lines+=['','## Resultado','','O Druida Sombrio avançou com os conjuntos: as três campanhas passaram do Panteão e pararam no Cataclismo. Ainda não alcançou o Paradoxo. O Avatar permaneceu no Panteão nas seis campanhas. O Protetor chegou ao Paradoxo em uma das seis, sem aumento da consistência observada em relação à amostra anterior.','','Portanto, os ajustes solicitados foram aplicados, mas a meta de todas as três rotas alcançarem o Paradoxo de forma consistente ainda não foi atingida. Isso não é uma avaliação da obrigação de vencer o último chefe.','','[Traços completos](qa/progression-nature-three-2026-11-09/results.json.gz).']
Path('docs/analise_natureza_tres_rotas_2026-11-09.md').write_text('\n'.join(lines)+'\n');(p/'results.json.gz').write_bytes(gzip.compress(json.dumps({'runs':data,'changes':'DOT45/refund15; avatar95/40 basic unchanged; cocoon1.7; God dodge25'},separators=(',',':')).encode()))
for f in files:f.unlink()
